import sys, json, time, pathlib
import numpy as np
from PIL import Image
sys.path.insert(0, '/opt/tools')
from rcb_client import Robot

OUT=pathlib.Path('/app/output')
R=Robot()
Q=np.array([0.,1.,0.,0.])

def now():
    return np.array(R.get_obs(video='none').meta['proprio']['now'][7:14],float)

def move(points, dt=.05, name='move', cameras=None, video='none'):
    cur=now()
    rows=[]
    for p in points:
        p=np.array(p,float)
        n=max(1,int(np.ceil(np.linalg.norm(p[:3]-cur[:3])/(0.004))))
        for j in range(1,n+1):rows.append(cur+(p-cur)*j/n)
        cur=p
    for k in range(0,len(rows),180):
        res=R.submit('ee_pose',np.array(rows[k:k+180]),dt=dt,cameras=cameras,video=video,note=name)
        print(name,k,len(rows),'now',res.meta['proprio']['now'][7:14],'plan',res.meta.get('plan'),'status',R.status(),flush=True)
        if video!='none':res.save(str(OUT/(name+'_'+str(k))))
    return res

def pose(x,y,z):return [x,y,z,*Q]

def snapshot(name,cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=False):
    o=R.get_obs(cameras=cameras,depth=depth,video='none')
    for c,im in o.last.items():Image.fromarray(im).save(OUT/(name+'_'+c+'.png'))
    if depth:
        for c,d in o.last_depth.items():np.save(OUT/(name+'_'+c+'_depth.npy'),d)
    print(name,'pose',o.meta['proprio']['now'][7:14],flush=True)
    return o

if __name__=='__main__':
    import argparse
    ap=argparse.ArgumentParser();ap.add_argument('cmd');a=ap.parse_args()
    if a.cmd=='practice_high':
        move([pose(-.1,-.1856,.10)],name='practice_high');snapshot('practice_high',depth=True)
