import numpy as np, heapq
from scipy import ndimage as ndi
from PIL import Image,ImageDraw
sk=np.load('/app/output/skeleton.npy');im=np.array(Image.open('/app/target.png').convert('RGB'));mask=im[:,:,0]<100
d=ndi.distance_transform_edt(mask)
S=set(map(tuple,np.argwhere(sk)))
def closest(u,v):return min(S,key=lambda p:(p[0]-v)**2+(p[1]-u)**2)
def path(a,b):
 src=closest(*a);dst=closest(*b);Q=[(0,src)];dist={src:0};parent={}
 while Q:
  cost,p=heapq.heappop(Q)
  if p==dst:break
  if cost>dist[p]:continue
  y,x=p
  for dy in [-1,0,1]:
   for dx in [-1,0,1]:
    if not (dx or dy):continue
    q=(y+dy,x+dx)
    if q not in S:continue
    nc=cost+(1.414213562 if dx and dy else 1)
    if nc<dist.get(q,1e20):dist[q]=nc;parent[q]=p;heapq.heappush(Q,(nc,q))
 out=[dst]
 while out[-1]!=src:out.append(parent[out[-1]])
 return [(x,y) for y,x in out[::-1]]
def multipath(way):
 out=[]
 for a,b in zip(way,way[1:]):out+=path(a,b)[:-1]
 out+=path(way[-2],way[-1])[-1:]
 return out
